package com.northstar.crm.service;

import com.northstar.crm.domain.*;import com.northstar.crm.repo.*;import com.northstar.crm.security.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;import static com.northstar.crm.domain.DomainTypes.*;
@Service public class EscalationService {
 public static final Map<EscalationStatus,Set<EscalationStatus>> ALLOWED_TRANSITIONS=Map.of(
  EscalationStatus.OPEN,Set.of(EscalationStatus.WAITING_ON_CUSTOMER,EscalationStatus.WAITING_ON_INTERNAL,EscalationStatus.RESOLVED),
  EscalationStatus.WAITING_ON_CUSTOMER,Set.of(EscalationStatus.OPEN,EscalationStatus.WAITING_ON_INTERNAL,EscalationStatus.RESOLVED),
  EscalationStatus.WAITING_ON_INTERNAL,Set.of(EscalationStatus.OPEN,EscalationStatus.WAITING_ON_CUSTOMER,EscalationStatus.RESOLVED),
  EscalationStatus.RESOLVED,Set.of(EscalationStatus.OPEN,EscalationStatus.CLOSED),EscalationStatus.CLOSED,Set.of(EscalationStatus.OPEN));
 private final EscalationRepository escalations;private final CommentRepository comments;private final OrganizationService organizations;private final ActorResolver actors;private final AccessPolicy access;private final AuditService audit;private final NotificationService notifications;private final UserRepository users;
 public EscalationService(EscalationRepository e,CommentRepository c,OrganizationService o,ActorResolver a,AccessPolicy p,AuditService audit,NotificationService n,UserRepository users){escalations=e;comments=c;organizations=o;actors=a;access=p;this.audit=audit;notifications=n;this.users=users;}
 @Transactional(readOnly=true) public List<Escalation> queue(){var actor=actors.current();return switch(actor.getRole()){case PLATFORM_ADMIN->escalations.findAll();case ACCOUNT_MANAGER->escalations.findByOrganizationIdInOrderByCreatedAtDesc(organizations.search("").stream().map(Organization::getId).toList());case SUPPORT_AGENT->escalations.findByAssignedAgentIdOrTeamIdOrderByCreatedAtDesc(actor.getId(),actor.getTeamId());case CUSTOMER_CONTACT->escalations.findByOrganizationIdOrderByCreatedAtDesc(actor.getOrganizationId());};}
 @Transactional(readOnly=true) public Escalation getAuthorized(UUID id){var actor=actors.current();var e=escalations.findById(id).orElseThrow(()->new NoSuchElementException("Escalation not found"));access.requireEscalation(actor,e);if(actor.getRole()==Role.ACCOUNT_MANAGER)organizations.getAuthorized(e.getOrganizationId());return e;}
 @Transactional(readOnly=true) public List<EscalationComment> comments(UUID id){var actor=actors.current();getAuthorized(id);return actor.getRole()==Role.CUSTOMER_CONTACT?comments.findByEscalationIdAndInternalOnlyFalseOrderByCreatedAt(id):comments.findByEscalationIdOrderByCreatedAt(id);}
 @Transactional public Escalation create(UUID orgId,String subject,Severity severity,String summary){var actor=actors.current();organizations.getAuthorized(orgId);if(subject==null||subject.isBlank()||subject.length()>160)throw new IllegalArgumentException("Subject required");if(summary==null||summary.isBlank()||summary.length()>2000)throw new IllegalArgumentException("Summary required");UUID agent=actor.getRole()==Role.SUPPORT_AGENT?actor.getId():null;var e=escalations.save(new Escalation(orgId,subject.strip(),severity,agent,actor.getTeamId(),summary.strip()));audit.record(actor,"ESCALATION_OPENED","Escalation",e.getId(),"{}","status=OPEN,severity="+severity,"authorized organization access");return e;}
 @Transactional public Escalation transition(UUID id,EscalationStatus next){var actor=actors.current();var e=getAuthorized(id);if(actor.getRole()==Role.CUSTOMER_CONTACT&&next!=EscalationStatus.OPEN)throw new org.springframework.security.access.AccessDeniedException("Customers may only reopen resolved requests");var before=e.getStatus();if(!ALLOWED_TRANSITIONS.getOrDefault(before,Set.of()).contains(next))throw new IllegalStateException("Transition "+before+" → "+next+" is not allowed");e.transition(next);audit.record(actor,"ESCALATION_STATUS_CHANGED","Escalation",id,"status="+before,"status="+next,"allowed edge; assigned/team/organization scope");notifyOrganization(e,"Request updated","“"+e.getSubject()+"” is now "+next.name().toLowerCase().replace('_',' '));return e;}
 @Transactional public EscalationComment addComment(UUID id,String body,boolean internalOnly){var actor=actors.current();var e=getAuthorized(id);if(body==null||body.isBlank()||body.length()>4000)throw new IllegalArgumentException("Comment must be 1–4,000 characters");if(actor.getRole()==Role.CUSTOMER_CONTACT&&internalOnly)throw new org.springframework.security.access.AccessDeniedException("Customers cannot create internal notes");var c=comments.save(new EscalationComment(id,actor.getId(),internalOnly,body.strip()));audit.record(actor,internalOnly?"INTERNAL_NOTE_ADDED":"CUSTOMER_UPDATE_ADDED","Escalation",id,"{}","commentId="+c.getId(),"escalation scope; visibility="+(internalOnly?"internal":"customer"));if(!internalOnly)notifyOrganization(e,"New request reply",e.getSubject());return c;}
 @Transactional public void assign(UUID id,UUID agentId){var actor=actors.current();if(actor.getRole()!=Role.PLATFORM_ADMIN&&actor.getRole()!=Role.SUPPORT_AGENT)throw new org.springframework.security.access.AccessDeniedException("Support access required");var e=getAuthorized(id);var agent=users.findById(agentId).filter(u->u.getRole()==Role.SUPPORT_AGENT&&u.isEnabled()).orElseThrow(()->new IllegalArgumentException("Active support agent required"));var before=String.valueOf(e.getAssignedAgentId());e.assign(agent.getId(),agent.getTeamId());audit.record(actor,"ESCALATION_ASSIGNED","Escalation",id,"agent="+before,"agent="+agent.getId(),"support team or admin");notifications.send(agent.getId(),"Escalation assigned",e.getSubject(),"escalations/"+id);}
 private void notifyOrganization(Escalation e,String title,String message){users.findByOrganizationId(e.getOrganizationId()).forEach(u->notifications.send(u.getId(),title,message,"escalations/"+e.getId()));}
}
